# Panel E: m6A Modification Density — Novel vs Known (Real Data from Server)
# Compact lollipop chart with reference line and embedded fraction annotation
library(data.table); library(ggplot2); library(scales)
source("../../shared/palette/color_palette.R")
out_dir <- "../output"

# REAL data from server (m6A 3'UTR, NC condition) — read from CSV
# Generated by Fig5_EGH_server.R on server: Seurat AverageExpression × m6A_gene_3utr_summary.csv.gz
density_file <- file.path("../data", "Fig5E_real_m6A_density.csv")
if (!file.exists(density_file)) {
  stop(sprintf("Density data file not found: %s. Run Fig5_EGH_server.R on server first.", density_file))
}
e_data <- fread(density_file)
cat(sprintf("Loaded %d categories from %s\n", nrow(e_data), density_file))
print(e_data)

e_data[, Category := factor(Category, levels=rev(c(
  "Known mRNA","Novel (k) contained","Novel (j) multi-exon","Novel (m) intron",
  "Novel (u) intergenic","Novel (i) intronic"
)))]
e_data[, PctDiff := (Sites_per_Gene / Sites_per_Gene[Category=="Known mRNA"] - 1) * 100]
e_data[, Direction := ifelse(PctDiff >= 0, "Higher", "Comparable")]
e_data[, Direction := factor(Direction, levels=c("Higher","Comparable"))]

# Build annotation labels
e_data[, Label := sprintf("  %.0f sites/gene  |  %s%.0f%%  |  %.2f%% modified  |  N=%d",
                          Sites_per_Gene,
                          ifelse(PctDiff >= 0, "+", ""), PctDiff,
                          Mean_Frac_NC * 100, N)]

# Color: red for higher, blue for known/reference
point_colors <- c("Higher" = "#D55E5E", "Comparable" = "#8CBFD0")

p <- ggplot(e_data) +
  # Reference band for known mRNA baseline
  annotate("rect", ymin=-Inf, ymax=Inf,
           xmin=e_data[Category=="Known mRNA", Sites_per_Gene] * 0.95,
           xmax=e_data[Category=="Known mRNA", Sites_per_Gene] * 1.05,
           fill="#8CBFD0", alpha=0.12) +
  # Reference line
  geom_vline(xintercept=e_data[Category=="Known mRNA", Sites_per_Gene],
             linetype="dashed", color="#8CBFD0", linewidth=0.7) +
  # Lollipop stems
  geom_segment(aes(x=0, xend=Sites_per_Gene, y=Category, yend=Category),
               color="grey60", linewidth=0.8) +
  # Points
  geom_point(aes(x=Sites_per_Gene, y=Category, fill=Direction),
             size=6, shape=21, color="white", stroke=0.8) +
  # Annotated labels to the right
  geom_text(aes(x=Sites_per_Gene, y=Category, label=Label),
            hjust=-0.08, size=3.5, family="mono") +
  # Colors
  scale_fill_manual(values=point_colors, guide="none") +
  # Explicit x-axis limits for label space
  scale_x_continuous(limits=c(0, 2050), expand=c(0,0)) +
  labs(x="m6A Sites per Gene (3'UTR, NC)",
       y=NULL,
       title="m6A Modification Density: Novel Transcript Host Genes vs Known mRNA",
       subtitle=paste0(
         "Server m6A 3'UTR data (11,664 genes). Novel(j) +40% vs known — ",
         "contradicts expectation that novel transcripts have reduced modification density")) +
  theme_drs +
  theme(
    axis.text.y = element_text(size=11, face="bold"),
    panel.grid.major.y = element_blank(),
    panel.grid.minor = element_blank(),
    plot.subtitle = element_text(size=8.5, color="grey40")
  )

pdf(file.path(out_dir, "Fig6C_Modification_Density.pdf"), w=12, h=3.5)
print(p)
dev.off()
png(file.path(out_dir, "Fig6C_Modification_Density.png"), w=12, h=3.5, units="in", res=300)
print(p)
dev.off()

cat("Fig5E optimized: compact lollipop chart, j+40% clearly highlighted.\n")
